<script>
(function(){
var _cs = document.currentScript;
function el(tag, attrs, txt){
  var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
  for (var k in attrs) e.setAttribute(k, attrs[k]);
  if (txt !== undefined) e.textContent = txt;
  return e;
}
var FF = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
function tx(s, x, y, size, weight, fill, anchor){
  return el("text", {x: x, y: y, "font-size": size, "font-weight": weight, fill: fill, "text-anchor": anchor, "font-family": FF}, s);
}
function fmt(v){ return String(Math.round(v)).replace(/\B(?=(\d{3})+(?!\d))/g, ","); }
var data = [{d:"Aug 31",v:36270.5},{d:"Sep 1",v:35825.7},{d:"Sep 2",v:36091.6},{d:"Sep 3",v:36633.1},{d:"Sep 4",v:36513.8},{d:"Sep 8",v:36123.1},{d:"Sep 9",v:35906.6},{d:"Sep 10",v:35506.3},{d:"Sep 11",v:35697.5},{d:"Sep 14",v:35702.5},{d:"Sep 15",v:35582.1},{d:"Sep 16",v:35491.3},{d:"Sep 17",v:35874.3},{d:"Sep 18",v:35806.7},{d:"Sep 21",v:36009.4},{d:"Sep 22",v:36335.6},{d:"Sep 23",v:35751.4},{d:"Sep 24",v:35706.5},{d:"Sep 25",v:35800.9},{d:"Sep 28",v:35489.9},{d:"Sep 29",v:35460.3},{d:"Sep 30",v:35235.9},{d:"Oct 1",v:35154.8},{d:"Oct 2",v:35502.7},{d:"Oct 5",v:35518.6},{d:"Oct 6",v:35649.5},{d:"Oct 7",v:35041.9},{d:"Oct 8",v:35145.4},{d:"Oct 9",v:35664.6},{d:"Oct 13",v:35984.0},{d:"Oct 14",v:35584.46}];
var n = data.length;
var margin = {left: 62, right: 24, top: 18, bottom: 46};
var PW = 594, PH = 236, MT = margin.top;
var vals = data.map(function(p){ return p.v; });
var lo = Math.min.apply(null, vals), hi = Math.max.apply(null, vals);
var pad = (hi - lo) * 0.12;
var yMin = Math.floor((lo - pad) / 200) * 200, yMax = Math.ceil((hi + pad) / 200) * 200;
function xp(i){ return margin.left + (i / (n - 1)) * PW; }
function yp(v){ return MT + (1 - (v - yMin) / (yMax - yMin)) * PH; }
var svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
svg.setAttribute("viewBox", "0 0 680 300");
svg.setAttribute("width", "100%");
var t;
for (t = yMin; t <= yMax; t += 400) {
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(t), y2: yp(t), stroke: "#ececec", "stroke-width": 0.5}));
}
var refY = yp(data[0].v);
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: refY, y2: refY, stroke: "#2e7d32", "stroke-width": 1, "stroke-dasharray": "3,3"}));
var d = "";
data.forEach(function(p, i){ d += (i === 0 ? "M" : "L") + xp(i).toFixed(1) + " " + yp(p.v).toFixed(1) + " "; });
svg.appendChild(el("path", {d: d, fill: "none", stroke: "#4a5568", "stroke-width": 1.8, "stroke-linejoin": "round"}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
var events = [
  {i: 23, l1: "OCT 2 U.S. PAYROLLS", l2: "TSX UP 0.99%", row: 0},
  {i: 28, l1: "OCT 9 CANADA JOBS", l2: "TSX UP 1.48%", row: 1},
  {i: 30, l1: "OCT 14 U.S. CPI", l2: "TSX DOWN 1.11%", row: 2}
];
events.forEach(function(ev){
  var ex = xp(ev.i);
  svg.appendChild(el("line", {x1: ex, x2: ex, y1: MT, y2: MT + PH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
});
var lastX = xp(n - 1), lastY = yp(data[n - 1].v);
svg.appendChild(el("circle", {cx: lastX, cy: lastY, r: 4, fill: "#4a5568"}));
var pillText = "35,584.46";
var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
var pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY + 8;
if (pillX < margin.left) pillX = margin.left;
svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
svg.appendChild(tx(pillText, pillX + pillW / 2, pillY + pillH / 2 + 3.5, 9, 700, "#111111", "middle"));
events.forEach(function(ev){
  var ex = xp(ev.i);
  var w = Math.max(ev.l1.length, ev.l2.length) * 7 * 0.68;
  var nearRight = (ex + w + 3) > (margin.left + PW);
  var anchor = nearRight ? "end" : "start";
  var dx = nearRight ? -4 : 3;
  var y0 = MT + 8 + ev.row * 20;
  var hx = (anchor === "end") ? (ex + dx - w - 2) : (ex + dx - 2);
  svg.appendChild(el("rect", {x: hx, y: y0 - 8, width: w + 4, height: 20, fill: "#ffffff", "fill-opacity": 0.92}));
  svg.appendChild(tx(ev.l1, ex + dx, y0, 7, 700, "#1a3560", anchor));
  svg.appendChild(tx(ev.l2, ex + dx, y0 + 9, 7, 700, "#1a3560", anchor));
});
for (t = yMin; t <= yMax; t += 400) {
  svg.appendChild(tx(fmt(t), margin.left - 6, yp(t) + 3, 8.5, 400, "#aaaaaa", "end"));
}
[0, 5, 10, 15, 20, 25, 30].forEach(function(i){
  var a = (i === n - 1) ? "end" : "middle";
  svg.appendChild(tx(data[i].d, xp(i), MT + PH + 14, 8, 400, "#999999", a));
});
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: TMX Group S&amp;P/TSX Composite daily closes via Yahoo Finance, Aug 31 to Oct 14, 2026; HDQ calculation. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">The dashed green line marks the August 31 close of 36,270.50. Daily moves summed without regard to direction total 21.2 percentage points against a net change of negative 1.9%.</p><h2>What the Next Two Releases Will and Will Not Settle</h2><p>Two more small samples arrive before the decisions. Statistics Canada reports September consumer prices on October 19, and Continuum Economics expects headline inflation to hold at 3.0% for a third month, with the Bank of Canada core measures edging slightly lower. The Federal Reserve and the Bank of Canada then both announce decisions on October 28, with the Canadian overnight rate at 2.25%, according to the Bank of Canada.</p><p>Professional forecasters do not agree on the outcome. TD Economics expects the Bank of Canada to hold in October, CIBC expects holds at both remaining 2026 meetings, and Capital Economics expects an increase soon to 2.75%, the midpoint of the neutral range. A spread like that is itself a statement about sample size: economists with full models and full data histories still disagree after one more print.</p><p>The behavioural point is narrow. Each of these releases is informative and none of them is conclusive. The sessions on October 9 and October 14 moved the composite 1.48% higher and 1.11% lower on releases that bore on the same policy question, with both central bank decisions still 13 days away.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">What They''re Feeling</div>
<p>Clients who follow headlines closely are feeling whiplash more than fear. A rally on bad Canadian jobs news on October 9 and a selloff on hot U.S. inflation news on October 14 seem to contradict each other, and many are asking which one to believe. Clients with large energy holdings feel relief mixed with unease, because the energy ETF XEG finished October 14 unchanged at $30.55 while the gold miners ETF XGD fell 4.2%. Clients with gold miner exposure are frustrated. Clients in balanced portfolios sense that the index went nowhere and want to know why it felt so rough getting there.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">What to Say</div>
<div class="script-box">I want to give you the picture of the last six weeks, not just the last two days. Since September 1 the TSX has had 11 days where it moved close to one per cent or more in one direction or the other, and it is down 1.9% over that stretch. That is a lot of movement for a small net result. Several of those days followed a single data release: a U.S. jobs report, a Canadian jobs report, a U.S. inflation report. Each one changed the market''s guess about whether the Federal Reserve or the Bank of Canada will raise rates on October 28, and each guess reversed within days. Your plan was not built on any one of those guesses. The next releases are Canadian inflation on October 19 and both central bank decisions on October 28, and I expect more movement around them. What I would like to do is confirm that your plan still fits your income needs and your time horizon, and leave it in place unless one of those has changed. Can we book fifteen minutes the week of October 19 to go through it together?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Who''s Affected</div>
<p><strong>High impact:</strong> clients who check balances daily or respond to news alerts, retirees with a withdrawal scheduled before October 28, and clients who have already phoned or emailed since October 9 asking whether to change something.</p>
<p><strong>Mixed impact:</strong> clients holding both energy and gold miners, who saw offsetting moves on October 14, and balanced-portfolio clients whose index exposure is close to flat since the end of August.</p>
<p><strong>Potential benefit:</strong> clients with cash waiting to be invested on a schedule, who are not forced sellers and can treat the swings as a reason to keep the schedule.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Action Checklist</div>
<div class="checklist-item">List every client who made contact since October 9 and note whether the contact followed a headline or a data release.</div>
<div class="checklist-item">Flag clients with withdrawals or contributions scheduled before October 28 and confirm the funding source for each.</div>
<div class="checklist-item">Calendar outreach for October 19 and October 28 so calls happen before the releases, not after.</div>
<div class="checklist-item">Pull each flagged client''s most recent risk questionnaire and stated time horizon before the call.</div>
<div class="checklist-item">Document each conversation, including the client''s stated reason for any request to change the plan.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Follow-Up Email Template</div>
<div class="email-box" id="respond-email">
<strong>Subject:</strong> Where things stand after two volatile weeks<br><br>
Hi [Client Name],<br><br>
Thank you for taking the time to talk today. As promised, here is the short version. Since September 1 the TSX has had 11 days with moves of about one per cent or more, and it is down 1.9% over the period. Several of those days followed a single data release, and the market''s view on central bank rate increases reversed several times. Your plan was designed to hold through periods like this one.<br><br>
Canadian inflation data arrives on October 19 and both the Federal Reserve and the Bank of Canada decide on October 28. I will be in touch before then. In the meantime, please call if your income needs or time horizon have changed.<br><br>
[Your Name]<br><br>
<em>This communication is for educational purposes only and does not constitute personalized investment advice.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copy email</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Client Profiles to Target</div>
<p><strong>DIY investors who traded around October 9 or October 14:</strong> a rally on bad jobs news followed by a selloff on hot inflation news is the kind of reversal that leaves a self-directed investor second-guessing with no one to ask.</p>
<p><strong>Self-directed investors holding both energy and gold miners:</strong> the October 14 split between the two exposed how much of the position depends on one rate view.</p>
<p><strong>Business owners with idle cash:</strong> owners waiting on a central bank decision before investing are exposed to the habit of reading each release as a verdict.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Opening Line</div>
<div class="script-box">The TSX has moved about one per cent or more on 11 days since September 1 and it is down 1.9% for the period, and several of those days followed one data release. I am calling people to ask how they have been handling it.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Value Proposition</div>
<p>The next six weeks hold two sets of scheduled catalysts: Canadian inflation on October 19 and both central bank decisions on October 28. A prospect managing money alone will meet each one with no framework for deciding whether a single print changes anything. The research on small samples is clear that it usually does not, and that the first reaction is the least reliable one.</p>
<p>The advisor offers a process in place of a reaction: a written plan, a stated time horizon and a call scheduled before the release. That is the asymmetry. The self-directed investor has a view on the next print. The advisor has a plan that does not depend on it.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Discovery Questions</div>
<div class="checklist-item">How have the last few weeks felt compared with what you expected from your portfolio?</div>
<div class="checklist-item">Did you make any changes after the jobs report or the inflation report?</div>
<div class="checklist-item">What would a bad outcome on October 28 look like for you, in dollars or in life terms?</div>
<div class="checklist-item">When you decide to buy or sell, what are you relying on, and how far back does it look?</div>
<div class="checklist-item">Who do you talk to when a number surprises you?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Prospecting Email Template</div>
<div class="email-box" id="prospect-email">
<strong>Subject:</strong> 11 big days, and the TSX is down 1.9%<br><br>
Hi [Prospect Name],<br><br>
Since September 1 the TSX has moved about one per cent or more on 11 days and is down 1.9% for the period. Several of those days followed a single jobs or inflation report. Another set of releases arrives on October 19 and October 28.<br><br>
Research on investor behaviour suggests the costly mistakes come from treating each release as a verdict. If it would be useful, I am happy to talk through how to prepare for those dates. Would 15 minutes this week work?<br><br>
[Your Name]<br><br>
<em>This communication is for educational purposes only and does not constitute personalized investment advice.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copy email</button>
</div>',
