var labelYOffsets = [-8, -8, 14];
var policy = 2.25;
var n = dates.length;
var margin = {left: 62, right: 24, top: 18, bottom: 46};
var PW = 594, PH = 236, MT = margin.top;
var all = [policy];
series.forEach(function(s){ all = all.concat(s.v); });
var lo = Math.min.apply(null, all), hi = Math.max.apply(null, all);
var pad = (hi - lo) * 0.1;
var yMin = Math.floor((lo - pad) * 5) / 5, yMax = Math.ceil((hi + pad) * 5) / 5;
function xp(i){ return margin.left + (i / (n - 1)) * PW; }
function yp(v){ return MT + (1 - (v - yMin) / (yMax - yMin)) * PH; }
function idxOf(lbl){ for (var i = 0; i < n; i++) { if (dates[i] === lbl) return i; } return 0; }
var svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
svg.setAttribute("viewBox", "0 0 680 300");
svg.setAttribute("width", "100%");
var t, ticks = [];
for (t = Math.ceil(yMin * 2) / 2; t <= yMax + 0.0001; t += 0.5) { ticks.push(Math.round(t * 100) / 100); }
ticks.forEach(function(v){
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(v), y2: yp(v), stroke: "#ececec", "stroke-width": 0.5}));
});
var refY = yp(policy);
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: refY, y2: refY, stroke: "#7a3030", "stroke-width": 1, "stroke-dasharray": "3,3"}));
