series.forEach(function(s){
  var d = "";
  s.v.forEach(function(val, i){ d += (i === 0 ? "M" : "L") + xp(i).toFixed(1) + " " + yp(val).toFixed(1) + " "; });
  svg.appendChild(el("path", {d: d, fill: "none", stroke: s.color, "stroke-width": s.w, "stroke-linejoin": "round"}));
});
svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
var events = [
  {lbl: "Sep 16", l1: "SEP 16 FED HIKES", l2: "TO 3.75% TO 4.00%", val: 85.5},
  {lbl: "Oct 14", l1: "OCT 14 HOT U.S. CPI", l2: "XGD FALLS 4.2%", val: 82}
];
events.forEach(function(ev){
  var ex = xp(idxOf(ev.lbl));
  svg.appendChild(el("line", {x1: ex, x2: ex, y1: MT, y2: MT + PH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
});
var lastX = xp(n - 1);
series.forEach(function(s){
  svg.appendChild(el("circle", {cx: lastX, cy: yp(s.v[n - 1]), r: 3, fill: s.color}));
});
var xeg = series[3];
var lastY = yp(xeg.v[n - 1]);
var pillText = "+7.5%";
var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
var pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY - pillH - 6;
svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
svg.appendChild(tx(pillText, pillX + pillW / 2, pillY + pillH / 2 + 3.5, 9, 700, "#111111", "middle"));
events.forEach(function(ev){
  var ex = xp(idxOf(ev.lbl));
  var w = Math.max(ev.l1.length, ev.l2.length) * 7 * 0.68;
  var nearRight = (ex + w + 3) > (margin.left + PW);
  var anchor = nearRight ? "end" : "start";
  var dx = nearRight ? -4 : 3;
  var y0 = yp(ev.val);
  var hx = nearRight ? (ex + dx - w - 2) : (ex + dx - 2);
  svg.appendChild(el("rect", {x: hx, y: y0 - 8, width: w + 4, height: 20, fill: "#ffffff", "fill-opacity": 0.92}));
  svg.appendChild(tx(ev.l1, ex + dx, y0, 7, 700, "#1a3560", anchor));
  svg.appendChild(tx(ev.l2, ex + dx, y0 + 9, 7, 700, "#1a3560", anchor));
});
series.forEach(function(s){
  svg.appendChild(tx(s.name, lastX - 5, yp(s.v[n - 1]) + s.off, 7.5, 700, "#666666", "end"));
});
ticks.forEach(function(tk){
  svg.appendChild(tx(String(tk), margin.left - 6, yp(tk) + 3, 8.5, 400, "#aaaaaa", "end"));
});
["Aug 31", "Sep 8", "Sep 16", "Sep 23", "Oct 1", "Oct 14"].forEach(function(l){
  var i = idxOf(l);
  var a = (i === n - 1) ? "end" : "middle";
  svg.appendChild(tx(dates[i], xp(i), MT + PH + 14, 8, 400, "#999999", a));
});
_cs.parentNode.appendChild(svg);
})();
</script>
